ST.xhtml:p:
R_Trriger(CLK := g_bFourSideUpLiftM);

IF R_Trriger.Q THEN
  g_boFourSideUpLift := FALSE;
  g_bFourSideUpLiftM := FALSE;
  bZUpLift := TRUE;
  dSquareLenght:= g_dSquareLenght;
  dSquareWidth:=g_dSquareWidth;
  dFollowheight := M.PARAMETER_P[176];
  nZUpLiftState := 10;
END_IF;

CASE nZUpLiftState OF
  0:
    nZUpLiftState := 0;
  10:
   dMaxHeight := SQRT(dSquareLenght*dSquareLenght/4.0 + dSquareWidth*dSquareWidth/4.0) - dFollowheight;
    IF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftCompen + dMaxHeight) <= g_fLiftCoord THEN
      dDistanceTemp := dUpLiftCompen + dMaxHeight;
    ELSIF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftCompen + dMaxHeight) > g_fLiftCoord AND (Axis_Z.NCTOPLC.ACTPOS + dMaxHeight) < g_fLiftCoord THEN
      dDistanceTemp := g_fLiftCoord - Axis_Z.NCTOPLC.ACTPOS;
    ELSIF (Axis_Z.NCTOPLC.ACTPOS + dMaxHeight) >= g_fLiftCoord THEN
      dDistanceTemp := dMaxHeight;
    END_IF;
    dDistanceTemp := Axis_Z.NcToPlc.ACTPOS + dDistanceTemp;
    IF dDistanceTemp >= g_fLiftCoord THEN
      dDistanceTemp := g_fLiftCoord;
    END_IF;
    nZUpLiftState := 15;
    g_bZRelDone := FALSE;
    g_bZRelExecute := FALSE;
  15:
    IF Axis_Z.NcToPlc.AXISSTATE = 2 THEN
      nZUpLiftState := 20;
    END_IF;
  20:
    g_fZRelDistance := dDistanceTemp - Axis_Z.NcToPlc.ACTPOS;
    g_fZRelVelocity := dLiftVelocity;
    g_bZRelExecute := TRUE;
    g_bZRelDone := FALSE;
     nZUpLiftState := 21;
  21:
  IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      g_boFourSideUpLift := TRUE;
      bZUpLift := FALSE;
      M.ENABLE[176] := 0;
      nZUpLiftState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nZUpLiftState := 200;
    END_IF;
  200:
    g_bZRelExecute := FALSE;
    IF g_bPlcStartBuffer THEN
      nZUpLiftState := 15;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  bZUpLift := FALSE;
  nZUpLiftState := 0;
  g_bZRelExecute := FALSE;
  g_boFourSideUpLift := FALSE;
END_IF;
